func (q *Queries) SetLeasePlannedEnd(ctx context.Context, arg SetLeasePlannedEndParams) (int64, error) {
	result, err := q.db.Exec(ctx, setLeasePlannedEnd, arg.OrganizationID, arg.ID, arg.PlannedEndDate)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateLeaseTerms = `-- name: UpdateLeaseTerms :execrows
UPDATE lease SET start_date = $3, deposit_amount = $4,
       collector_staff_user_id = $5, billed_from = $6, updated_at = now()
WHERE organization_id = $1 AND id = $2 AND status = 'active'
`

type UpdateLeaseTermsParams struct {
	OrganizationID       uuid.UUID
	ID                   uuid.UUID
	StartDate            time.Time
	DepositAmount        int64
	CollectorStaffUserID uuid.NullUUID
	BilledFrom           time.Time
}

// Only an active lease changes. Unit, tenant and term never change: end the lease and start
// another.
func (q *Queries) UpdateLeaseTerms(ctx context.Context, arg UpdateLeaseTermsParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateLeaseTerms,
		arg.OrganizationID,
		arg.ID,
		arg.StartDate,
		arg.DepositAmount,
		arg.CollectorStaffUserID,
		arg.BilledFrom,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateTenant = `-- name: UpdateTenant :one
UPDATE tenant SET name = $3, phone = $4, note = $5, updated_at = now()
WHERE organization_id = $1 AND id = $2
RETURNING id, organization_id, name, phone, note, created_at, updated_at
`

type UpdateTenantParams struct {
	OrganizationID uuid.UUID
	ID             uuid.UUID
	Name           string
	Phone          string
	Note           string
}

func (q *Queries) UpdateTenant(ctx context.Context, arg UpdateTenantParams) (Tenant, error) {
	row := q.db.QueryRow(ctx, updateTenant,
		arg.OrganizationID,
		arg.ID,
		arg.Name,
		arg.Phone,
		arg.Note,
	)
	var i Tenant
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.Name,
		&i.Phone,
		&i.Note,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
